import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE emp (id INTEGER PRIMARY KEY, name TEXT, dept TEXT);
INSERT INTO emp VALUES (1,'Ann','Eng'), (2,'Cy','Sales');
CREATE VIEW eng AS SELECT id, name, dept FROM emp WHERE dept = 'Eng';
-- SQLite views are read-only; INSTEAD OF triggers make them writable
CREATE TRIGGER eng_ins INSTEAD OF INSERT ON eng BEGIN
  SELECT RAISE(ABORT, 'WITH CHECK OPTION failed') WHERE NEW.dept <> 'Eng';
  INSERT INTO emp (name, dept) VALUES (NEW.name, NEW.dept);
END;
CREATE TRIGGER eng_upd INSTEAD OF UPDATE ON eng BEGIN
  SELECT RAISE(ABORT, 'WITH CHECK OPTION failed') WHERE NEW.dept <> 'Eng';
  UPDATE emp SET name = NEW.name, dept = NEW.dept WHERE id = OLD.id;
END;
""")
db.execute("INSERT INTO eng (name, dept) VALUES ('Bob', 'Eng')")
print("after insert via view:", db.execute("SELECT * FROM emp").fetchall())
for sql in ("INSERT INTO eng (name, dept) VALUES ('Eve', 'Sales')",
            "UPDATE eng SET dept = 'Sales' WHERE id = 1"):
    try:
        db.execute(sql)
    except sqlite3.DatabaseError as e:
        print("rejected:", sql, "->", e)
print("final emp:", db.execute("SELECT * FROM emp").fetchall())

import sqlite3

db = sqlite3.connect(":memory:", isolation_level=None)  # we control BEGIN/COMMIT
db.executescript("""
CREATE TABLE acct (id INTEGER PRIMARY KEY, bal INT CHECK (bal >= 0));
INSERT INTO acct VALUES (1, 100), (2, 50);
CREATE TABLE transfers (src INT, dst INT, amt INT);
-- trigger acts as the "procedure": validate, then move the money
CREATE TRIGGER do_transfer AFTER INSERT ON transfers BEGIN
  SELECT RAISE(ABORT, 'insufficient funds')
    WHERE (SELECT bal FROM acct WHERE id = NEW.src) < NEW.amt;
  UPDATE acct SET bal = bal - NEW.amt WHERE id = NEW.src;
  UPDATE acct SET bal = bal + NEW.amt WHERE id = NEW.dst;
END;
""")
show = lambda: db.execute("SELECT * FROM acct").fetchall()
print("start:", show())

def transfer(src, dst, amt):
    db.execute("BEGIN")
    try:
        db.execute("INSERT INTO transfers VALUES (?, ?, ?)", (src, dst, amt))
        db.execute("COMMIT")
        print("ok   ", src, "->", dst, amt, show())
    except sqlite3.DatabaseError as e:
        db.execute("ROLLBACK")      # nothing is half-applied
        print("fail ", src, "->", dst, amt, e, show())

transfer(1, 2, 30)
transfer(2, 1, 500)

import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE product (id INTEGER PRIMARY KEY, name TEXT, price INT);
CREATE TABLE audit (id INTEGER PRIMARY KEY, tbl TEXT, pk INT, action TEXT, old_row TEXT, new_row TEXT);

CREATE TRIGGER p_ins AFTER INSERT ON product BEGIN
  INSERT INTO audit (tbl, pk, action, new_row) VALUES
    ('product', NEW.id, 'INSERT', json_object('name', NEW.name, 'price', NEW.price));
END;
-- WHEN skips no-op updates
CREATE TRIGGER p_upd AFTER UPDATE ON product
WHEN OLD.name IS NOT NEW.name OR OLD.price IS NOT NEW.price BEGIN
  INSERT INTO audit (tbl, pk, action, old_row, new_row) VALUES
    ('product', NEW.id, 'UPDATE', json_object('name', OLD.name, 'price', OLD.price),
     json_object('name', NEW.name, 'price', NEW.price));
END;
CREATE TRIGGER p_del AFTER DELETE ON product BEGIN
  INSERT INTO audit (tbl, pk, action, old_row) VALUES
    ('product', OLD.id, 'DELETE', json_object('name', OLD.name, 'price', OLD.price));
END;
""")
db.execute("INSERT INTO product (name, price) VALUES ('pen', 5)")
db.execute("UPDATE product SET price = 7 WHERE id = 1")
db.execute("UPDATE product SET price = 7 WHERE id = 1")   # no-op: not audited
db.execute("DELETE FROM product WHERE id = 1")
for r in db.execute("SELECT id, action, old_row, new_row FROM audit"): print(r)
